// Blob-triggered Azure Function for CSV ingestion
module.exports = async function (context, myBlob) {
    const csv = myBlob.toString();
    const lines = csv.split('\n');
    const header = lines[0].split(',');

    // Validate required header
    const required = ['id', 'timestamp', 'value'];
    if (!required.every(h => header.includes(h))) {
        context.log.error('Invalid header');
        return;
    }

    // Parse and transform rows
    const cleanData = lines.slice(1)
        .filter(line => line.trim())
        .map(line => {
            const values = line.split(',');
            return {
                id: values[0],
                timestamp: new Date(values[1]).toISOString(),
                value: parseFloat(values[2])
            };
        });

    // Write to ADLS Gen2 at /tenants/{tenantId}/clean
};
```

